INSERT INTO tb_help_request (user_id, category_id, title, description, reward, address, lng, lat, status, urgent, create_time, update_time) VALUES
(115, 6, '求教初三数学，函数这块不太懂', '孩子初三，函数图像和二次函数不太理解，希望能找个大学生或者老师辅导一下。', 50.00, '阳光苑小区5栋1单元101', 116.3985, 39.9162, 1, 1, NOW(), NOW()),
(109, 2, '厨房水槽下水道堵了，急求疏通', '厨房水槽这两天排水越来越慢，今天彻底堵死了。试了热水和皮搋子都不管用。', 30.00, '翠竹园小区3栋401', 116.4012, 39.9178, 1, 1, NOW(), NOW()),
(110, 4, '帮忙取个快递，驿站快关门了', '有个京东快递在小区门口菜鸟驿站，我今天加班赶不回去，驿站9点关门。', 8.00, '翠竹园小区门口菜鸟驿站', 116.3998, 39.9155, 1, 0, NOW(), NOW()),
(113, 6, '小学四年级英语辅导，找个大学生', '孩子英语基础不太好，单词记不住，语法也不开窍。想找个有耐心的大学生帮忙辅导。', 40.00, '金色家园小区6栋201', 116.3972, 39.9148, 1, 0, NOW(), NOW()),
(114, 9, '陪老爷子下楼遛弯一小时', '老爷子今年78，腿脚不太方便但又不愿意老在家待着。我今天腰扭了实在没法陪着。', 25.00, '翠竹园小区8栋301', 116.4005, 39.9168, 1, 0, NOW(), NOW()),
(111, 1, '空调不制冷了，求维修师傅', '卧室空调开了半天吹出来的风一点都不凉，滤网洗过了也没用，估计是缺氟。', 60.00, '阳光苑小区3栋602', 116.3978, 39.9159, 1, 1, NOW(), NOW()),
(115, 3, '搬个小沙发从一楼到三楼', '买了个二手小沙发，一米五的双人小沙发，一个人搬上三楼确实费劲，求搭把手。', 20.00, '金色家园小区1栋301', 116.3968, 39.9142, 1, 0, NOW(), NOW()),
(110, 10, '借个冲击钻用半天', '想在墙上打两个孔装挂画，自己的电钻头打不动，借个冲击钻用一下半天就还。', 5.00, '翠竹园小区2栋502', 116.3995, 39.9152, 1, 0, NOW(), NOW()),
(113, 5, '出差三天，求帮忙喂猫', '这周五到周日出差，家里有只英短蓝猫需要人每天过来喂粮换水铲猫砂，东西都备好了。', 30.00, '金色家园小区7栋401', 116.3975, 39.9151, 1, 0, NOW(), NOW()),
(112, 7, '笔记本电脑开不了机，急修', 'ThinkPad用了三年，今天突然开不了机了，按电源键完全没反应，里面有很多工作文件。', 80.00, '阳光苑小区2栋1501', 116.3982, 39.9165, 1, 1, NOW(), NOW()),
(109, 8, '帮忙看看租房合同有没有坑', '刚毕业第一次租房，中介给的合同有些条款看着不太对劲，想找个懂的人帮忙看一眼。', 15.00, '翠竹园小区1栋202', 116.4008, 39.9160, 1, 0, NOW(), NOW()),
(114, 10, '手机掉小区池塘里了，求帮忙打捞', '在小区凉亭拍照手滑手机掉进景观池塘了，水不深大概半米，但我腿脚不好下不去。', 35.00, '翠竹园小区中心花园景观池塘', 116.4001, 39.9172, 1, 1, NOW(), NOW());
